package com.emp.ems;
import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpStatus;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import software.amazon.awssdk.regions.Region;import software.amazon.awssdk.services.s3.model.PutObjectRequest;import software.amazon.awssdk.services.s3.presigner.S3Presigner;import software.amazon.awssdk.services.s3.presigner.model.PutObjectPresignRequest;import java.time.Duration;import java.util.*;
/** Image bytes upload directly to S3; only the asset address is stored in PostgreSQL. */
@RestController @RequestMapping("/api/v1/employee/assets")
public class AssetController{private final String bucket,region;AssetController(@Value("${ems.storage.bucket}")String bucket,@Value("${ems.storage.region}")String region){this.bucket=bucket;this.region=region;}record Upload(String uploadUrl,String assetUrl,int expiresInSeconds,Map<String,List<String>> requiredHeaders){}
 @PostMapping("/upload-url")Upload upload(@AuthenticationPrincipal CurrentUser user){if(bucket.isBlank())throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"External asset storage is not configured.");String key="telemetry/"+user.id()+"/"+UUID.randomUUID()+".jpg";try(S3Presigner signer=S3Presigner.builder().region(Region.of(region)).build()){var request=PutObjectRequest.builder().bucket(bucket).key(key).contentType("image/jpeg").serverSideEncryption("AES256").build();var signed=signer.presignPutObject(PutObjectPresignRequest.builder().signatureDuration(Duration.ofMinutes(5)).putObjectRequest(request).build());return new Upload(signed.url().toString(),"https://"+bucket+".s3."+region+".amazonaws.com/"+key,300,signed.signedHeaders());}}
}
